 compound:{t:'₹10,000/month SIP — value over time',r:()=>{ const rows=[5,10,15,20,25].map(y=>{ const r=0.12/12,n=y*12; const fv=10000*((Math.pow(1+r,n)-1)/r)*(1+r); return [y+' years',bkInr(10000*n),bkInr(fv)]; }); return fig('compound','₹10,000 a month at 12% a year — invested vs value',`<div class="hbars">${rows.map(([y,i,v])=>{ const vv=+v.replace(/[₹,]/g,''); return `<div class="hb"><span>${y}</span><span class="hb-t"><i style="width:${vv/1e7*100}%"></i></span><b>${v}</b></div>`; }).join('')}</div>${T(['Period','Invested','Value at 12%'],rows)}`,'Illustrative; returns are not guaranteed. Shows how the last years add the most — compounding.'); }},
